test('validateCustomer needs an id, a name and an email', () => {
  assert.equal(validateCustomer({ id: 'C-100', name: 'X', email: 'x@y.example' }).ok, true);
  assert.deepEqual(validateCustomer({ id: 'C-100', name: 'X', email: 'nope' }), { ok: false, error: 'CUSTOMER_INVALID' });
});

test('mergeCustomers removes fromId and keeps intoId', () => {
  const customers = listCustomers();
  const result = mergeCustomers(customers, [], 'C-001', 'C-002');
  assert.equal(result.ok, true);
  assert(!result.value.customers.some((c) => c.id === 'C-001'));
  assert(result.value.customers.some((c) => c.id === 'C-002'));
});

test('mergeCustomers returns correct count of customers', () => {
  const customers = listCustomers();
  const original = customers.length;
  const result = mergeCustomers(customers, [], 'C-001', 'C-002');
  assert.equal(result.value.customers.length, original - 1);
});

test('mergeCustomers updates invoices with fromId', () => {
  const customers = listCustomers();
  const invoices = [
    { number: 'INV-001', customerId: 'C-001' },
    { number: 'INV-002', customerId: 'C-002' },
  ];
  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(result.ok, true);
  assert(result.value.invoices.some((inv) => inv.number === 'INV-001' && inv.customerId === 'C-002'));
});

test('mergeCustomers leaves other invoices unchanged', () => {
  const customers = listCustomers();
  const invoices = [
    { number: 'INV-001', customerId: 'C-001' },
    { number: 'INV-002', customerId: 'C-002' },
    { number: 'INV-003', customerId: 'C-003' },
  ];
  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(result.value.invoices.length, 3);
  assert(result.value.invoices.some((inv) => inv.number === 'INV-003' && inv.customerId === 'C-003'));
});

test('mergeCustomers updates multiple invoices from same customer', () => {
  const customers = listCustomers();
  const invoices = [
    { number: 'INV-001', customerId: 'C-001' },
    { number: 'INV-002', customerId: 'C-001' },
    { number: 'INV-003', customerId: 'C-002' },
  ];
  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(result.ok, true);
  const mergedInvoices = result.value.invoices.filter((inv) => inv.customerId === 'C-002');
  assert.equal(mergedInvoices.length, 3);
});

test('mergeCustomers returns error if fromId not found', () => {
  const customers = listCustomers();
  const result = mergeCustomers(customers, [], 'C-999', 'C-001');
  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('mergeCustomers returns error if intoId not found', () => {
  const customers = listCustomers();
  const result = mergeCustomers(customers, [], 'C-001', 'C-999');
  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('mergeCustomers returns error if both ids not found', () => {
  const customers = listCustomers();
  const result = mergeCustomers(customers, [], 'C-999', 'C-998');
  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('mergeCustomers returns SAME_CUSTOMER error if ids are identical', () => {
  const customers = listCustomers();
  const result = mergeCustomers(customers, [], 'C-001', 'C-001');
  assert.deepEqual(result, { ok: false, error: 'SAME_CUSTOMER' });
});

test('mergeCustomers normalizes customer ids', () => {
  const customers = listCustomers();
  const result = mergeCustomers(customers, [], 'c-001', 'C-002');
  assert.equal(result.ok, true);
  assert(!result.value.customers.some((c) => c.id === 'C-001'));
});

test('mergeCustomers handles lowercase into id', () => {
  const customers = listCustomers();
  const result = mergeCustomers(customers, [], 'C-001', 'c-002');
  assert.equal(result.ok, true);
  assert(result.value.customers.some((c) => c.id === 'C-002'));
});

test('mergeCustomers case-insensitive SAME_CUSTOMER check', () => {
  const customers = listCustomers();
  const result = mergeCustomers(customers, [], 'c-001', 'C-001');
  assert.deepEqual(result, { ok: false, error: 'SAME_CUSTOMER' });
});

test('mergeCustomers returns immutable result', () => {
  const customers = listCustomers();
  const invoices = [{ number: 'INV-001', customerId: 'C-001' }];
  const originalCustomerCount = customers.length;
  const originalInvoiceCount = invoices.length;

  mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(customers.length, originalCustomerCount);
  assert.equal(invoices.length, originalInvoiceCount);
  assert.equal(invoices[0].customerId, 'C-001');
});

test('mergeCustomers with empty invoices list', () => {
  const customers = listCustomers();
  const result = mergeCustomers(customers, [], 'C-001', 'C-002');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
});

test('mergeCustomers preserves all invoice data', () => {
  const customers = listCustomers();
  const invoices = [
    { number: 'INV-001', customerId: 'C-001', amount: 50000, status: 'issued' },
  ];
  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  const merged = result.value.invoices[0];
  assert.equal(merged.number, 'INV-001');
  assert.equal(merged.amount, 50000);
  assert.equal(merged.status, 'issued');
  assert.equal(merged.customerId, 'C-002');
});

test('mergeCustomers result has customers and invoices keys', () => {
  const customers = listCustomers();
  const result = mergeCustomers(customers, [], 'C-001', 'C-002');
  assert('customers' in result.value);
  assert('invoices' in result.value);
});

test('mergeCustomers preserves all customers except fromId', () => {
  const customers = listCustomers();
  const result = mergeCustomers(customers, [], 'C-005', 'C-010');
  const customerIds = result.value.customers.map((c) => c.id);
  assert(customerIds.includes('C-001'));
  assert(customerIds.includes('C-002'));
  assert(!customerIds.includes('C-005'));
  assert(customerIds.includes('C-010'));
});

